:root {
  --bg: #1a1c2c;
  --card: #29366f;
  --panel: #41a6f6;
  --text: #f4f4f4;
  --accent: #ffcd75;
  --accent-dark: #b13e53;
  --border: #0b0d18;
  --focus: #a7f070;
}

* {
  box-sizing: border-box;
}

html, body {
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px 16px;
  background-color: var(--bg);
  background-image:
    linear-gradient(45deg, rgba(255, 255, 255, 0.04) 25%, transparent 25%, transparent 75%, rgba(255, 255, 255, 0.04) 75%),
    linear-gradient(45deg, rgba(255, 255, 255, 0.04) 25%, transparent 25%, transparent 75%, rgba(255, 255, 255, 0.04) 75%);
  background-size: 32px 32px;
  background-position: 0 0, 16px 16px;
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  font-size: 18px;
  color: var(--text);
}

.card {
  width: 100%;
  max-width: 420px;
  background: var(--card);
  border: 4px solid var(--border);
  box-shadow: 8px 8px 0 var(--border);
  padding: 28px 24px 32px;
}

h1 {
  margin: 0 0 24px;
  font-size: 1.6rem;
  text-align: center;
  color: var(--accent);
  letter-spacing: 1px;
  text-shadow: 3px 3px 0 var(--border);
}

.field {
  margin-bottom: 20px;
  border: none;
  padding: 0;
}

label, legend {
  display: block;
  margin-bottom: 8px;
  font-weight: 700;
  color: var(--text);
}

input {
  width: 100%;
  padding: 12px 14px;
  font: inherit;
  color: var(--text);
  background: var(--bg);
  border: 3px solid var(--border);
  border-radius: 0;
  outline: none;
}

input::placeholder {
  color: rgba(244, 244, 244, 0.5);
}

input:focus-visible {
  border-color: var(--focus);
  box-shadow: 0 0 0 3px var(--focus);
}

.tip-buttons {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 10px;
}

.tip-btn {
  font: inherit;
  font-weight: 700;
  padding: 12px 4px;
  color: var(--text);
  background: var(--panel);
  border: 3px solid var(--border);
  border-radius: 0;
  cursor: pointer;
  transition: transform 0.05s ease, background 0.15s ease;
}

.tip-btn:hover {
  background: #6bb8f8;
}

.tip-btn:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.tip-btn:active {
  transform: translate(2px, 2px);
}

.tip-btn[aria-pressed="true"] {
  background: var(--accent);
  color: var(--border);
}

.tip-btn[aria-pressed="true"]:hover {
  background: #ffe09a;
}

.error {
  margin: 6px 0 0;
  min-height: 1em;
  font-size: 0.9rem;
  color: var(--accent);
}

.results {
  margin-top: 8px;
  padding: 18px;
  background: var(--bg);
  border: 3px solid var(--border);
}

.result-row {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 12px;
  padding: 6px 0;
}

.result-row.total {
  margin-top: 8px;
  padding-top: 14px;
  border-top: 3px dashed var(--border);
}

.result-label {
  font-weight: 700;
}

.result-value {
  font-size: 1.35rem;
  font-weight: 800;
  color: var(--accent);
  white-space: nowrap;
}

.result-row.total .result-value {
  font-size: 1.6rem;
  color: var(--focus);
}

@media (max-width: 400px) {
  body {
    padding: 16px 10px;
  }
  .card {
    padding: 22px 16px 26px;
  }
  h1 {
    font-size: 1.35rem;
  }
  .result-value {
    font-size: 1.2rem;
  }
  .result-row.total .result-value {
    font-size: 1.4rem;
  }
}

(function () {
  'use strict';

  var billInput = document.getElementById('bill');
  var peopleInput = document.getElementById('people');
  var billError = document.getElementById('bill-error');
  var peopleError = document.getElementById('people-error');
  var tipAmountEl = document.getElementById('tip-amount');
  var totalPerPersonEl = document.getElementById('total-per-person');
  var tipButtons = Array.prototype.slice.call(document.querySelectorAll('.tip-btn'));

  var selectedTipPercent = 15;

  function formatCurrency(value) {
    return '$' + value.toFixed(2);
  }

  function setError(el, message) {
    el.textContent = message || '';
  }

  function selectTipButton(button) {
    tipButtons.forEach(function (btn) {
      btn.setAttribute('aria-pressed', btn === button ? 'true' : 'false');
    });
    selectedTipPercent = Number(button.getAttribute('data-tip'));
    calculate();
  }

  function calculate() {
    var billRaw = billInput.value.trim();
    var peopleRaw = peopleInput.value.trim();
    var valid = true;

    var bill = parseFloat(billRaw);
    if (billRaw === '' || isNaN(bill) || bill < 0) {
      setError(billError, billRaw === '' ? '' : 'Enter a valid bill amount (0 or more).');
      if (billRaw !== '') valid = false;
      bill = 0;
    } else {
      setError(billError, '');
    }

    var people = parseInt(peopleRaw, 10);
    if (peopleRaw === '' || isNaN(people) || people < 1 || String(people) !== peopleRaw.replace(/^0+(?=\d)/, '')) {
      setError(peopleError, peopleRaw === '' ? 'Enter at least 1 person.' : 'Enter a whole number of 1 or more.');
      valid = false;
      people = 0;
    } else {
      setError(peopleError, '');
    }

    if (!valid || people < 1) {
      tipAmountEl.textContent = formatCurrency(0);
      totalPerPersonEl.textContent = formatCurrency(0);
      return;
    }

    var tip = bill * (selectedTipPercent / 100);
    var totalPerPerson = (bill + tip) / people;

    tipAmountEl.textContent = formatCurrency(tip);
    totalPerPersonEl.textContent = formatCurrency(totalPerPerson);
  }

  tipButtons.forEach(function (button) {
    button.addEventListener('click', function () {
      selectTipButton(button);
    });

    button.addEventListener('keydown', function (event) {
      var index = tipButtons.indexOf(button);
      var nextIndex = null;

      if (event.key === 'ArrowRight' || event.key === 'ArrowDown') {
        nextIndex = (index + 1) % tipButtons.length;
      } else if (event.key === 'ArrowLeft' || event.key === 'ArrowUp') {
        nextIndex = (index - 1 + tipButtons.length) % tipButtons.length;
      } else if (event.key === 'Home') {
        nextIndex = 0;
      } else if (event.key === 'End') {
        nextIndex = tipButtons.length - 1;
      }

      if (nextIndex !== null) {
        event.preventDefault();
        tipButtons[nextIndex].focus();
        selectTipButton(tipButtons[nextIndex]);
      }
    });
  });

  billInput.addEventListener('input', calculate);
  peopleInput.addEventListener('input', calculate);

  calculate();
})();
